// Command protofixture writes, or reads back, the port scan alert the daemon
// sends to the GUI.
//
// It exists so the Go bindings can be checked against the two Python
// generations the GUI picks between at import time. Those three
// implementations of the same message are generated by three different
// compilers, and a disagreement between any two of them shows up as a GUI that
// starts, connects, and silently never displays a scan -- which is exactly the
// failure a shape-only test cannot see.
//
// Usage:
//
//	protofixture --write alert.bin
//	protofixture --read  alert.bin
//
// ui/opensnitch/proto/check_portscan_bindings.py builds the same message and
// takes the same arguments, so either side can write and either can read.
package main

import (
	"fmt"
	"os"

	"github.com/evilsocket/opensnitch/daemon/ui/protocol"
	"google.golang.org/protobuf/proto"
)

// sample must stay identical, field for field, to sample() in
// check_portscan_bindings.py. That is the whole point: the two sides are
// written independently against the same .proto and must agree byte for byte.
func sample() *protocol.Alert {
	scan := &protocol.PortScan{
		SrcIp:                "2001:db8::66",
		SrcMac:               "02:11:22:33:44:55",
		SrcMacIsSourceOwn:    false,
		Method:               "tcp-xmas",
		MethodDetail:         "TCP Xmas scan (nmap -sX)",
		FlagsSummary:         "**u*p**f",
		DistinctPorts:        42,
		MinPort:              1,
		MaxPort:              65535,
		SamplePorts:          []uint32{1, 2, 3, 4, 5},
		Protocols:            3,
		IsProtocolScan:       false,
		Score:                200,
		Interface:            "eth0",
		Targets:              []string{"2001:db8::1"},
		Anomalies:            []string{"ip-fragment"},
		HasTcpEvidence:       true,
		BlockEligible:        true,
		SuppressedSince:      99,
		BlockDurationSeconds: 14400,
		FirstSeenUnixnano:    1700000000000000000,
		LastSeenUnixnano:     1700000002000000000,
	}
	return &protocol.Alert{
		What:     protocol.Alert_PORT_SCAN,
		Portscan: scan,
	}
}

func check(a *protocol.Alert) error {
	if a.GetWhat() != protocol.Alert_PORT_SCAN {
		return fmt.Errorf("what = %v, want PORT_SCAN", a.GetWhat())
	}
	p := a.GetPortscan()
	if p == nil {
		return fmt.Errorf("the alert carries no port scan")
	}
	for _, c := range []struct {
		name string
		got  interface{}
		want interface{}
	}{
		{"src_ip", p.GetSrcIp(), "2001:db8::66"},
		{"src_mac", p.GetSrcMac(), "02:11:22:33:44:55"},
		// False is the load-bearing value: the MAC belongs to the last router,
		// not to the source, and a client must be able to tell.
		{"src_mac_is_source_own", p.GetSrcMacIsSourceOwn(), false},
		{"method", p.GetMethod(), "tcp-xmas"},
		{"distinct_ports", p.GetDistinctPorts(), uint32(42)},
		{"suppressed_since", p.GetSuppressedSince(), uint64(99)},
		{"block_duration_seconds", p.GetBlockDurationSeconds(), uint32(14400)},
		{"first_seen_unixnano", p.GetFirstSeenUnixnano(), int64(1700000000000000000)},
	} {
		if c.got != c.want {
			return fmt.Errorf("%s = %v, want %v", c.name, c.got, c.want)
		}
	}
	if n := len(p.GetSamplePorts()); n != 5 {
		return fmt.Errorf("sample_ports has %d entries, want 5", n)
	}
	if len(p.GetAnomalies()) != 1 || p.GetAnomalies()[0] != "ip-fragment" {
		return fmt.Errorf("anomalies = %v", p.GetAnomalies())
	}
	return nil
}

func main() {
	if len(os.Args) != 3 {
		fmt.Fprintln(os.Stderr, "usage: protofixture --write|--read <file>")
		os.Exit(2)
	}
	mode, path := os.Args[1], os.Args[2]

	switch mode {
	case "--write":
		raw, err := proto.Marshal(sample())
		if err != nil {
			fmt.Fprintf(os.Stderr, "marshalling: %v\n", err)
			os.Exit(1)
		}
		if err := os.WriteFile(path, raw, 0o644); err != nil {
			fmt.Fprintf(os.Stderr, "writing %s: %v\n", path, err)
			os.Exit(1)
		}
		fmt.Printf("wrote %s (%d bytes) with the Go bindings\n", path, len(raw))

	case "--read":
		raw, err := os.ReadFile(path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "reading %s: %v\n", path, err)
			os.Exit(1)
		}
		var a protocol.Alert
		if err := proto.Unmarshal(raw, &a); err != nil {
			fmt.Fprintf(os.Stderr, "parsing %s: %v\n", path, err)
			os.Exit(1)
		}
		if err := check(&a); err != nil {
			fmt.Fprintf(os.Stderr, "FAIL: %v\n", err)
			os.Exit(1)
		}
		fmt.Printf("parsed %s with the Go bindings\n", path)

	default:
		fmt.Fprintf(os.Stderr, "unknown mode %q\n", mode)
		os.Exit(2)
	}
}
